create or replace function public.enforce_incident_update_permissions() returns trigger language plpgsql security definer set search_path = public as $$ begin if public.is_super_admin((select auth.uid())) then return new; end if; if public.is_campus_admin((select auth.uid())) then if old.campus is distinct from public.get_user_campus((select auth.uid())) then raise exception 'Campus officers may only update incidents for their assigned campus'; end if; return new; end if; if old.submitted_by = (select auth.uid()) or old.reporter_id = (select auth.uid()) then if new.id is distinct from old.id or new.title is distinct from old.title or new.description is distinct from old.description or new.category is distinct from old.category or new.status is distinct from old.status or new.is_anonymous is distinct from old.is_anonymous or new.reporter_id is distinct from old.reporter_id or new.submitted_by is distinct from old.submitted_by or new.assigned_to is distinct from old.assigned_to or new.resolved_at is distinct from old.resolved_at or new.resolved_by is distinct from old.resolved_by or new.resolution_notes is distinct from old.resolution_notes or new.signature_data is distinct from old.signature_data or new.campus is distinct from old.campus or new.created_at is distinct from old.created_at then raise exception 'Students may only update live location fields on their own incident'; end if; return new; end if; raise exception 'Not authorised to update this incident'; end; $$;